// The human checkout on a REAL Postgres (src/human-checkout.js with
// STATE_DATABASE_URL): the record directory is imported once at the first
// boot and never again, every record is a row (and, while the directory
// exists, a file), a paid session is generated by exactly one of two
// instances that fulfil it at once, a stale claim is taken over by exactly
// one of two sweeps, a failed report is refunded and an unrefunded one is
// owed on the row, and a published report is served by the synchronous
// public readers from the mirror. Requires STATE_DATABASE_URL (CI fails
// without it).
import "./lib/own-stats.js"; // a stats store of this suite's own (see the file)
import { mkdtempSync, rmSync, writeFileSync, readFileSync, existsSync, utimesSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, basename } from "node:path";
import { requireTestPg } from "./lib/test-pg.js";
requireTestPg({ label: "test-human-checkout-pg" });
const sdb = await import("../src/state-db.js");
const { createHumanCheckout, readPublicReport, listPublicReports, refreshPublicMirror, STALE_CLAIM_MS, ensureHumanCheckoutIndexes, HUMAN_CHECKOUT_INDEXES, HUMAN_CHECKOUT_ERROR_ROWS_SQL } = await import("../src/human-checkout.js");

let pass = 0, fail = 0;
const ok = (c, m) => { if (c) { pass++; console.log(`ok - ${m}`); } else { fail++; console.error(`FAIL - ${m}`); } };
const DIR = mkdtempSync(join(tmpdir(), "human-checkout-pg-"));
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
let clock = Date.parse("2026-10-01T12:00:00Z");
const now = () => clock;
const row = async (id) => (await sdb.stateQuery(`SELECT body FROM ${sdb.stateDbSchema()}.records WHERE collection = 'human-checkout' AND id = $1`, [id])).rows[0]?.body ?? null;
const file = (id) => { try { return JSON.parse(readFileSync(join(DIR, `${id}.json`), "utf8")); } catch { return null; } };

// The directory a previous build left: one delivered public report, one
// stale claim in flight, one owed refund.
const OLD_PUBLIC = "rp_oldoldoldoldold";
writeFileSync(join(DIR, "cs_done.json"), JSON.stringify({ status: "done", kind: "domain", slug: "domain-audit", input: "example.com", title: "example.com", report: "# Domain Security Audit: example.com\n\nText.", sources: [], tables: [], at: "2026-09-01T00:00:00.000Z", public: true, publicId: OLD_PUBLIC, publishedAt: "2026-09-02T00:00:00.000Z" }));
writeFileSync(join(DIR, "_public.json"), JSON.stringify({ [OLD_PUBLIC]: "cs_done" }));
writeFileSync(join(DIR, "cs_stale.json"), JSON.stringify({ status: "generating", kind: "dossier", slug: "dossier", at: new Date(clock - STALE_CLAIM_MS - 1000).toISOString(), claimedAt: clock - STALE_CLAIM_MS - 1000, takeovers: 0 }));
writeFileSync(join(DIR, "_inflight.json"), JSON.stringify({ cs_stale: clock - STALE_CLAIM_MS - 1000 }));
writeFileSync(join(DIR, "cs_owed.json"), JSON.stringify({ status: "error", refundId: null, error: "We couldn't complete this report. Your refund is being processed.", refundOwed: true, refundAttempts: 1, lastRefundAttemptAt: clock - 60_000, paymentIntent: "pi_owed", at: new Date(clock - 60_000).toISOString() }));
writeFileSync(join(DIR, "_issues.json"), JSON.stringify({ cs_owed: { kind: "refund-owed", at: new Date(clock - 60_000).toISOString(), attempts: 1 } }));

const sessions = {
  // The session behind the imported owed record: a report purchase, which is what the retry now reads before it refunds.
  cs_owed: { id: "cs_owed", mode: "payment", payment_status: "paid", payment_intent: "pi_owed", metadata: { product: "research", input: "FAIL" } },
  cs_paid: { id: "cs_paid", payment_status: "paid", payment_intent: "pi_ok", customer_details: { email: null }, metadata: { product: "dossier", input: "AAPL" } },
  cs_fail: { id: "cs_fail", payment_status: "paid", payment_intent: "pi_fail", metadata: { product: "research", input: "FAIL" } },
  cs_stale: { id: "cs_stale", payment_status: "paid", payment_intent: "pi_stale", metadata: { product: "dossier", input: "MSFT" } },
  cs_slow: { id: "cs_slow", payment_status: "paid", payment_intent: "pi_slow", metadata: { product: "dossier", input: "SLOW" } },
};
let refunds = [];
let refundFail = false;
let genCalls = 0;
const stripe = {
  checkout: { sessions: { retrieve: async (id) => { await wait(15); const s = sessions[id]; if (!s) throw new Error("No such session"); return s; } } },
  refunds: {
    create: async (args) => { if (refundFail) throw new Error("stripe refund down"); refunds.push(args); return { id: "re_" + refunds.length, status: "succeeded" }; },
    // A payment refunded by hand in the Stripe dashboard (read back, never re-refunded).
    list: async ({ payment_intent }) => ({ data: payment_intent === "pi_cap" ? [{ id: "re_cap", status: "succeeded", created: 1 }] : payment_intent === "pi_cap_part" ? [{ id: "re_cap_part", status: "succeeded", created: 1 }] : [] }),
  },
  paymentIntents: { retrieve: async (id) => ({ id, latest_charge: { refunded: id === "pi_cap" } }) },
};
const sales = [];
const generate = async (kind, slug, input) => {
  genCalls++;
  if (input === "FAIL") throw new Error("upstream boom");
  if (input === "SLOW") await wait(150);
  return { report: `# REPORT (${slug})\n\nAnalysis of ${input}. [1]`, title: `T:${input}`, sources: [], tables: [] };
};
// indexDelayMs null: the suite builds the owed list's index itself, below.
const mk = () => createHumanCheckout({ stripe, generate, baseUrl: "https://agent402.tools", storeDir: DIR, onSale: (s) => sales.push(s), now, log: () => {}, indexDelayMs: null });
// Polls until the record leaves "generating", up to a deadline: a busy CI
// runner can take well over a second to land the final record.
async function settle(hc, id, deadlineMs = 10_000) {
  const until = Date.now() + deadlineMs;
  while (Date.now() < until) { const r = await hc.peek(id); if (r && r.status !== "generating") return r; await wait(10); }
  return hc.peek(id);
}

try {
  // ---- (1) import once ------------------------------------------------------
  const A = mk();
  ok(A.backend === "pg", "the store is on the database");
  await A.ready();
  ok(!!(await sdb.imports.done(basename(DIR))), "the directory import is marked under its basename");
  ok((await row("cs_done"))?.publicId === OLD_PUBLIC && (await row("_inflight"))?.cs_stale > 0 && (await row("_issues"))?.cs_owed?.kind === "refund-owed", "records and the three indexes were imported as rows");
  ok((await A._count()) === 3, "three report records");
  writeFileSync(join(DIR, "cs_late.json"), JSON.stringify({ status: "done", kind: "dossier", slug: "dossier", input: "LATE", report: "# late", at: "2026-09-01T00:00:00.000Z" }));
  const B = mk();
  await B.ready();
  ok((await B.peek("cs_late")) === null && (await row("cs_late")) === null, "a second boot does not import again");

  // ---- the public readers serve the mirror, synchronously -------------------
  await refreshPublicMirror();
  const view = readPublicReport(OLD_PUBLIC, "/nonexistent");
  ok(view?.publicView === true && view.input === "example.com" && listPublicReports("/nonexistent").some((r) => r.publicId === OLD_PUBLIC), "an imported public report is served by the synchronous readers from the mirror (no directory needed)");
  ok(readPublicReport("rp_000000000000000000") === null && readPublicReport("cs_done") === null, "unknown and session-shaped ids read nothing");

  // ---- (2) generate once across two instances --------------------------------
  const [f1, f2] = await Promise.all([A.fulfill("cs_slow"), B.fulfill("cs_slow")]);
  ok(f1.status === "generating" && f2.status === "generating", "both instances answer generating to the buyer");
  const done = await settle(A, "cs_slow");
  await settle(B, "cs_slow");
  // The row reads done as soon as it lands; the sale is booked just after, so
  // wait for it on the same deadline before counting.
  for (const until = Date.now() + 10_000; sales.length < 1 && Date.now() < until;) await wait(10);
  ok(done.status === "done" && genCalls === 1 && sales.length === 1, `two instances fulfilling one paid session at once generate it ONCE (generate calls: ${genCalls}, status: ${done.status}, sales: ${sales.length})`);
  ok((await row("cs_slow"))?.status === "done" && (await row("_inflight"))?.cs_slow === undefined, "the delivered record is the row and the in-flight index no longer lists it");
  ok(file("cs_slow")?.status === "done" && file("_inflight")?.cs_slow === undefined, "the record and the index are written through to the directory");
  ok((await B.fulfill("cs_slow")).status === "done" && genCalls === 1, "a later poll on the other instance reads the row and does not regenerate");

  // ---- (3) the stale claim is taken over by exactly one sweep --------------
  const before = genCalls;
  const [r1, r2] = await Promise.all([A.recoverAbandoned(), B.recoverAbandoned()]);
  await settle(A, "cs_stale");
  ok(genCalls === before + 1 && (await row("cs_stale"))?.status === "done", `two boot sweeps over one stale claim regenerate it once (${JSON.stringify([r1, r2].map((r) => r.map((x) => x.result)))})`);
  // A record another container finished is never overwritten by a claim.
  const [f3, f4] = await Promise.all([A.fulfill("cs_paid"), B.fulfill("cs_paid")]);
  const paid = await settle(A, "cs_paid");
  ok(f3.status === "generating" && f4.status === "generating" && paid.status === "done" && genCalls === before + 2, "a fresh paid session fulfilled by both instances is generated once");

  // ---- (4) a failed report is refunded; a failed refund is owed on the row --
  refundFail = true;
  await A.fulfill("cs_fail");
  const failed = await settle(A, "cs_fail");
  // The record lands first and the issues index is patched just after it
  // (afterFinal), so wait for the index on the same deadline.
  for (const until = Date.now() + 10_000; (await row("_issues"))?.cs_fail?.kind !== "refund-owed" && Date.now() < until;) await wait(10);
  ok(failed.status === "error" && failed.refundOwed === true && !failed.refundId && (await row("_issues"))?.cs_fail?.kind === "refund-owed", "a failed report whose refund fails is persisted as OWED and indexed");
  const issues = await B.listIssues();
  ok(issues.refundOwed.some((x) => x.id === "cs_fail") && issues.refundOwed.some((x) => x.id === "cs_owed") && issues.inflight.length === 0, "listIssues on the other instance reads the rows");
  refundFail = false;
  clock += 60_000;
  const retried = await B.fulfill("cs_fail");
  ok(retried.status === "error" && retried.refundId === "re_1" && retried.refundOwed === false && (await row("_issues"))?.cs_fail === undefined, "a later poll retries the owed refund, succeeds, and clears the issue");
  const owed = await A.fulfill("cs_owed");
  ok(owed.refundId === "re_2" && owed.refundOwed === false && file("cs_owed")?.refundId === "re_2", "an imported owed refund is retried and the outcome written through");

  // ---- (4b) the owed list comes from the records, not only the index -------
  // The index is patched in a statement after the record: a failure in
  // between leaves an owed record unindexed, or a refunded one indexed.
  const putRow = (id, body) => sdb.stateQuery(`INSERT INTO ${sdb.stateDbSchema()}.records (collection, id, body) VALUES ('human-checkout', $1, $2::jsonb) ON CONFLICT (collection, id) DO UPDATE SET body = EXCLUDED.body`, [id, JSON.stringify(body)]);
  const unidx = { status: "error", refundId: null, refundOwed: true, refundAttempts: 4, lastRefundAttemptAt: 0, paymentIntent: "pi_unidx", product: "research", at: new Date(clock - 20 * 60_000).toISOString(), error: "x" };
  await putRow("cs_unidx", unidx);
  await putRow("_issues", { ...((await row("_issues")) || {}), cs_fail: { kind: "refund-owed", at: new Date(clock).toISOString(), attempts: 1 }, cs_idxonly: { kind: "refund-owed", at: new Date(clock).toISOString(), attempts: 1, product: "research" } });
  const listed = (await B.listIssues()).refundOwed;
  ok(listed.some((x) => x.id === "cs_unidx" && x.attempts === 4 && x.at === unidx.at && x.product === "research"), `an owed record the index never caught is listed (${JSON.stringify(listed.map((x) => x.id))})`);
  ok(!listed.some((x) => x.id === "cs_fail") && (await row("cs_fail"))?.refundId === "re_1", "an index entry whose record shows the refund was sent is not listed");
  ok(listed.some((x) => x.id === "cs_idxonly") && !listed.some((x) => x.id === "cs_paid"), "control: an index entry with no record is listed, a delivered report is not");
  const owedIds = (await A.owedRefunds()).map((x) => x.id);
  ok(owedIds.includes("cs_unidx") && !owedIds.includes("cs_fail"), `the owed list the refundsOwed word reads agrees (${JSON.stringify(owedIds)})`);
  await putRow("cs_unidx", { ...unidx, refundId: "re_x", refundOwed: false });
  await putRow("_issues", Object.fromEntries(Object.entries((await row("_issues")) || {}).filter(([k]) => k !== "cs_fail" && k !== "cs_idxonly")));
  // The error records are read at most once per few seconds per container
  // (the list is read by a public, uncached surface): another container's
  // write shows once that bound passes.
  ok((await B.listIssues()).refundOwed.some((x) => x.id === "cs_unidx"), "inside the cache bound another container's write is not read yet (one statement per bound)");
  clock += 6_000;
  ok(!(await B.listIssues()).refundOwed.some((x) => x.id === "cs_unidx"), "once its record shows the refund it leaves the list, within the cache bound");
  await putRow("cs_unidx2", { ...unidx, paymentIntent: "pi_unidx2" });
  ok(!(await B.listIssues()).refundOwed.some((x) => x.id === "cs_unidx2"), "setup: the new owed record is inside B's cache bound");
  await B.setPublic("cs_paid", false);
  ok((await B.listIssues()).refundOwed.some((x) => x.id === "cs_unidx2"), "a write by this container drops its cache at once");
  await putRow("cs_unidx2", { ...unidx, paymentIntent: "pi_unidx2", refundId: "re_y", refundOwed: false });
  clock += 6_000;
  // A refund Stripe holds and has not finished: the row's refundPending
  // reaches the owed list (the refundsOwed word's card=pending) on the database.
  await putRow("cs_pendrow", { ...unidx, paymentIntent: "pi_pendrow", refundPending: true });
  await putRow("cs_plainrow", { ...unidx, paymentIntent: "pi_plainrow" });
  clock += 6_000;
  const pendList = Object.fromEntries((await B.owedRefunds()).filter((x) => x.id === "cs_pendrow" || x.id === "cs_plainrow").map((x) => [x.id, x.pending]));
  ok(pendList.cs_pendrow === true && pendList.cs_plainrow === false, `pg: the owed list says which refund is pending at Stripe (${JSON.stringify(pendList)})`);
  await putRow("cs_pendrow", { ...unidx, paymentIntent: "pi_pendrow", refundId: "re_p", refundOwed: false });
  await putRow("cs_plainrow", { ...unidx, paymentIntent: "pi_plainrow", refundId: "re_q", refundOwed: false });
  clock += 6_000;

  // ---- (4c) the background read-back past the retry cap ---------------------
  // Rows at refundAttempts 6 are no longer retried on a poll; the read-back
  // records a dashboard refund on the row and leaves a partial one owed,
  // issuing no refund itself.
  await putRow("cs_cap", { ...unidx, refundAttempts: 6, paymentIntent: "pi_cap" });
  await putRow("cs_cap_part", { ...unidx, refundAttempts: 6, paymentIntent: "pi_cap_part" });
  clock += 6_000;
  const createsBefore = refunds.length;
  const rb = await A.readBackOwedRefunds();
  ok(rb.recorded === 1 && refunds.length === createsBefore, `the read-back records one dashboard refund and issues none (${JSON.stringify(rb)})`);
  ok((await row("cs_cap"))?.refundId === "re_cap" && (await row("cs_cap"))?.refundOwed === false && !(await row("cs_cap_part"))?.refundId, "the dashboard-refunded row is recorded on the database; the partial one stays owed");
  clock += 6_000;
  const owedAfter = (await B.owedRefunds()).map((x) => x.id);
  ok(!owedAfter.includes("cs_cap") && owedAfter.includes("cs_cap_part"), `the other container's owed list drops it (${JSON.stringify(owedAfter)})`);
  await putRow("cs_cap_part", { ...unidx, refundAttempts: 6, paymentIntent: "pi_cap_part", refundId: "re_cap_part", refundOwed: false });
  clock += 6_000;

  // ---- (5) the public toggle updates the row and the mirror -----------------
  const pubOn = await A.setPublic("cs_paid", true);
  ok(pubOn.status === "done" && /^rp_/.test(pubOn.publicId) && readPublicReport(pubOn.publicId)?.input === "AAPL" && (await row("_public"))?.[pubOn.publicId] === "cs_paid", "publishing mints the id on the row, in the index and in the mirror");
  const pubOff = await A.setPublic("cs_paid", false);
  ok(pubOff.public === false && readPublicReport(pubOn.publicId) === null && !listPublicReports().some((r) => r.publicId === pubOn.publicId), "revoking drops it from the mirror and the list");
  ok((await B.setPublic("cs_nope_0000", true)).status === "not_found" && (await B.setPublic("junk", true)).status === "invalid", "publishing needs a real, delivered session id");
  await B.setPublic("cs_paid", true);
  await refreshPublicMirror();
  ok(readPublicReport(pubOn.publicId)?.publicId === pubOn.publicId && file("cs_paid")?.public === true, "a re-publish from the other instance reaches this mirror on refresh, and the file");
  ok(existsSync(join(DIR, "cs_paid.json")), "the record file exists for the write-through");

  // ---- (5b) two toggles at once mint one public id ------------------------------
  // Each read the row with no publicId; the id is minted by one conditional
  // statement, so both answer the same id and the index holds one entry.
  const race = { status: "done", kind: "dossier", slug: "dossier", input: "RACE", title: "T:RACE", report: "# race", sources: [], tables: [], at: new Date(clock).toISOString() };
  await putRow("cs_race", race);
  const [ra, rb2] = await Promise.all([A.setPublic("cs_race", true), B.setPublic("cs_race", true)]);
  const raceRow = await row("cs_race");
  const raceIdx = Object.entries((await row("_public")) || {}).filter(([, sid]) => sid === "cs_race").map(([k]) => k);
  ok(ra.publicId && ra.publicId === rb2.publicId && raceRow?.publicId === ra.publicId && raceIdx.join() === ra.publicId,
    `two toggles at once mint one public id, answered to both, on the row and once in the index (${ra.publicId} / ${rb2.publicId} / row ${raceRow?.publicId} / index ${raceIdx.join(",")})`);
  ok(raceRow?.public === true && raceRow.report === "# race", "the toggle merges its flag into the row and keeps the report");
  // Many at once, on several rows: every toggle of a row answers that row's one id.
  const many = [];
  for (let k = 0; k < 4; k++) {
    const id = `cs_race${k}`;
    await putRow(id, { ...race, input: `RACE${k}` });
    many.push(Promise.all(Array.from({ length: 6 }, (_, j) => (j % 2 ? A : B).setPublic(id, true))).then((outs) => ({ id, ids: [...new Set(outs.map((o) => o.publicId))] })));
  }
  const manyOut = await Promise.all(many);
  const pubIdx = (await row("_public")) || {};
  const manyBad = [];
  for (const { id, ids } of manyOut) {
    const indexed = Object.entries(pubIdx).filter(([, sid]) => sid === id).map(([k]) => k);
    if (ids.length !== 1 || indexed.length !== 1 || indexed[0] !== ids[0] || (await row(id))?.publicId !== ids[0]) manyBad.push(`${id}: answered ${ids.join(",")} indexed ${indexed.join(",")}`);
  }
  ok(manyBad.length === 0, `six toggles at once on each of four rows mint one id per row (${manyBad.join("; ") || "one each"})`);
  const raceOff = await A.setPublic("cs_race", false);
  const raceOn = await B.setPublic("cs_race", true);
  ok(raceOff.public === false && raceOn.publicId === ra.publicId && (await row("cs_race"))?.publicId === ra.publicId, "a revoke and a re-publish keep the one id");

  // ---- (6) roll-forward: files written in a rollback window win per id -----
  writeFileSync(join(DIR, "cs_paid.json"), JSON.stringify({ ...file("cs_paid"), title: "ROLLED" }));
  const C = mk();
  await C.ready();
  ok((await row("cs_paid")).title === "T:AAPL", "a record file written within the write-through grace is not re-read (the row stays)");
  const future = (Date.now() + 120_000) / 1000;
  utimesSync(join(DIR, "cs_paid.json"), future, future);
  const ROLLED = "rp_rolledrolledrol";
  writeFileSync(join(DIR, "cs_rolled.json"), JSON.stringify({ status: "done", kind: "dossier", slug: "dossier", input: "ROLL", title: "T:ROLL", report: "# rolled", sources: [], tables: [], at: new Date(clock).toISOString(), public: true, publicId: ROLLED, publishedAt: new Date(clock).toISOString() }));
  writeFileSync(join(DIR, "_public.json"), JSON.stringify({ ...file("_public"), [ROLLED]: "cs_rolled" }));
  utimesSync(join(DIR, "_public.json"), future, future);
  const D = mk();
  await D.ready();
  ok((await row("cs_paid")).title === "ROLLED" && (await row("cs_rolled"))?.status === "done", "roll-forward: records dated past the grace win over the rows, and a record born in the window exists");
  ok((await row("_public"))?.[ROLLED] === "cs_rolled" && readPublicReport(ROLLED)?.input === "ROLL", "roll-forward: the public index written in the window is the index, and the mirror serves the report");

  // ---- (7) the owed list's partial index, built CONCURRENTLY --------------------
  // Built outside any transaction and the boot's schema lock, once; an
  // INVALID one a failed build left is dropped and built again; the owed
  // list's statement can use it.
  ok(typeof ensureHumanCheckoutIndexes === "function" && Array.isArray(HUMAN_CHECKOUT_INDEXES), "the store exports its index build");
  if (typeof ensureHumanCheckoutIndexes === "function") {
    const schemaName = sdb.stateDbSchema();
    const ix = HUMAN_CHECKOUT_INDEXES[0];
    const idx = async () => Object.fromEntries((await sdb.stateQuery(`SELECT c.relname AS name, i.indisvalid AS valid FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = $1 AND c.relname = ANY($2)`, [schemaName, HUMAN_CHECKOUT_INDEXES.map((x) => x.name)])).rows.map((r) => [r.name, r.valid]));
    ok(Object.keys(await idx()).length === 0, "no owed-list index exists before the build runs (the stores here were made with the background build off)");
    await sdb.stateStatementOutsideTx(`CREATE UNIQUE INDEX CONCURRENTLY ${ix.name} ON ${schemaName}.records ((body->>'status')) WHERE collection = 'human-checkout'`).catch(() => {});
    ok((await idx())[ix.name] === false, "a failed concurrent build leaves an invalid index (the case the build repairs)");
    const built = await ensureHumanCheckoutIndexes({ log: () => {} });
    ok(built.ran === true && (await idx())[ix.name] === true && built.result?.rebuilt?.join() === ix.name, `the invalid one is dropped and the index built valid (${JSON.stringify(built.result)})`);
    const again = await ensureHumanCheckoutIndexes({ log: () => {} });
    ok(again.ran === true && again.result?.built?.length === 0, `a second run builds nothing (${JSON.stringify(again.result)})`);
    const plan = (await sdb.withStateTx(async (c) => { await c.query("SET LOCAL enable_seqscan = off"); return (await c.query(`EXPLAIN ${HUMAN_CHECKOUT_ERROR_ROWS_SQL(`${schemaName}.records`)}`)).rows.map((r) => r["QUERY PLAN"]).join("\n"); }));
    ok(plan.includes(ix.name), `the owed list's statement can use the index (${plan.split("\n")[0]})`);
    clock += 6_000;
    ok(Array.isArray((await B.listIssues()).refundOwed), "the owed list reads the same with the index in place");
  }
} finally {
  await sdb.__dropStateSchema().catch(() => {});
  await sdb.closeStateDb();
  rmSync(DIR, { recursive: true, force: true });
}
console.log(`\ntest-human-checkout-pg: ${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
